import{_ as n,l,o as e,c as o,v as t,p as i,x as r,d as V,i as d,S as s}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"到 XVA 的桥","description":"","frontmatter":{"title":"到 XVA 的桥","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/xva-bridge.md","filePath":"quant/xva-bridge.md","lastUpdated":1789023840000}'),h={name:"quant/xva-bridge.md"};function p(E,a,c,u,C,_){const A=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="到-xva-的桥" tabindex="-1">到 XVA 的桥 <a class="header-anchor" href="#到-xva-的桥" aria-label="Permalink to &quot;到 XVA 的桥&quot;">​</a></h1><div class="epigraph"><p>无违约、无抵押、无资金摩擦的风险中性价格，只是 XVA 展开的第一项；后面每一项都是对同一暴露路径抽一次不同的费用。</p><footer>—— Gregory, The xVA Challenge；对照 Burgard–Kjaer 对资金与对冲的复制论述</footer></div><p><a href="/quant/quoting-conventions">上一课</a>把报价惯例写成坐标变换：内部用统一 \\((T,K)\\)，对冲再用 Jacobian 换回市场语言。缺口是柜台价还不是入账价。主干 <a href="/quant/cva-lite">CVA 要点</a> 已写对手方违约的那一项；本课当桥，把 CVA、DVA、FVA、MVA、KVA 放进同一暴露引擎。不重讲 ATM 定义。后课 FX 与商品仍用无 XVA 的定价核起步；结构票据与净额集要回到这座桥。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前台模型给出 \\(V^{\\mathrm{clean}}\\)。入账要减 CVA、加 DVA、加减资金（FVA）、减初始保证金的资金（MVA）、以及资本费用（KVA，若内部经济资本要进价）。问题是这些调整<strong>共用</strong>模拟的暴露 \\(V_t\\)，但乘的曲线不同：CDS 生存、自身 CDS、资金利差、IM 规则、资本权重。把 XVA 当「在 clean 价格上加几个基点」，等于假定暴露是常数贷款，Gregory 已否定。</p><p>净额与 CSA 改变 \\(V_t^+\\) 的形状：有抵押时 CVA 小、MVA 大。同一张 autocallable，在不同净额集里的 XVA 可以差一个数量级。拆解课的「债 + 期权」在 XVA 层变成「净额集 + 保证金协议 + 资本」。</p><h3 id="不要把-dva-当利润留存" tabindex="-1">不要把 DVA 当利润留存 <a class="header-anchor" href="#不要把-dva-当利润留存" aria-label="Permalink to &quot;不要把 DVA 当利润留存&quot;">​</a></h3><p><a href="/quant/dva-own-credit">DVA</a> 是自身信用变差时的账面收益。对冲它要用自己的信用，实务几乎做不到，很多机构把 DVA 从交易员 PnL 剔除。桥的任务是让会计、限额、交易员三套数字能对上哪一项在哪张表，而不是争论 DVA 是否「真实」。</p><p><span class="marginnote">FVA 是否进入无套利价格，文献有争议（Hull–White vs 实务资金台）。实现上资金曲线是真实约束；模型上应把假设写进确认，避免与 CVA 双重计算同一信用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一条暴露引擎：市场因子路径 → 按前台模型重估每笔 → 按净额集与 CSA 聚合 → 输出 EE、PFE、IM 路径。CVA 用 EE 与对手方违约密度，见 CVA 课。MVA 用 <a href="/quant/mva-initial-margin">初始保证金</a> 路径的资金成本。KVA 用资本路径的成本。AAD 穿过暴露引擎才能给 XVA 的市场桶，否则只有 clean Vega。</p><p>新产品接入：先问进哪个净额集、何种 CSA、是否强制 IM，再问用哪套前台模型。没有这三问，奇异校准再精细也只是 clean 世界。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Clean 价格假设可以无摩擦复制。XVA 把摩擦写回：对手方可能消失、你可能消失、你借钱有利差、监管要 IM 与资本。每一项都是对同一 \\(V_t\\) 路径的不同泛函。因此模型风险与校准误差会<strong>杠杆式</strong>进入 XVA：障碍在壁附近的暴露尖峰，CVA 与 IM 都放大。Cont 的模型带在 XVA 上通常比在 clean 价格上更宽。</p>',14)),(e(),i(s,null,{default:r(()=>[d(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Clean%5B%22%E5%89%8D%E5%8F%B0%20clean%20%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20Exp%5B%22%E5%87%80%E9%A2%9D%E9%9B%86%E6%9A%B4%E9%9C%B2%E8%B7%AF%E5%BE%84%22%5D%0A%20%20Exp%20--%3E%20CVA%5B%22CVA%20%E5%AF%B9%E6%89%8B%E6%96%B9%22%5D%0A%20%20Exp%20--%3E%20DVA%5B%22DVA%20%E8%87%AA%E8%BA%AB%22%5D%0A%20%20Exp%20--%3E%20FVA%5B%22FVA%20%E8%B5%84%E9%87%91%22%5D%0A%20%20Exp%20--%3E%20MVA%5B%22MVA%20%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20Exp%20--%3E%20KVA%5B%22KVA%20%E8%B5%84%E6%9C%AC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[V(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>双重计算：CVA 已含信用，FVA 的信用部分要扣。代理对冲（指数 CDS）留下基差，那是另一条 XVA。流动性枯竭时 CSA 争议与估值代理失效，EE 模型低估。本课不给「最优 XVA 对冲」清单；对象是架构上的桥。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Clean 价格是 XVA 的第一项；其余项共用暴露路径、分乘不同曲线。</li><li>净额与 CSA 决定形状；新产品先问净额集再问模型。</li><li>模型带在 XVA 上更宽；AAD 必须穿过暴露引擎。</li><li>出处：Gregory, <em>The xVA Challenge</em>；Burgard and Kjaer 关于资金复制的论文。</li></ul>',4))])}const D=n(h,[["render",p]]);export{B as __pageData,D as default};
